{"kind":"tool","id":"f0r1WebgBJ8","toolName":"write_file","input":{"path":"api/_lib/routes/admin-email-templates.ts","instructions":"Add a protected API for reading and saving validated structured email template overrides.","content":"import { ApiError, endpoint, parseJsonBody, sendJson } from '../http.js';
import { requireAdmin } from '../staff.js';
import { parseInput, emailTemplateSaveSchema } from '../validation.js';
import { emailTemplateCatalog, templateDefinition } from '../email-templates.js';
import { saveEmailTemplateOverride } from '../db.js';
import { recordAudit } from '../audit.js';

export default endpoint({ methods: ['GET', 'PUT'], csrf: true }, async (req, res) => {
  const session = await requireAdmin(req, res);
  if (req.method === 'GET') {
    sendJson(res, 200, { templates: await emailTemplateCatalog() });
    return;
  }

  const data = parseInput(emailTemplateSaveSchema, parseJsonBody(req));
  const definition = templateDefinition(data.id);
  const content = {
    ...data.content,
    ...(definition.securitySensitive ? { actionUrl: undefined } : {}),
  };
  // Undefined is not valid JSON and the database never stores action URLs for
  // security templates; their destinations are supplied by the send flow.
  if (definition.securitySensitive) delete (content as { actionUrl?: unknown }).actionUrl;
  await saveEmailTemplateOverride({
    templateId: data.id,
    content,
    updatedBy: session.userId,
  });
  await recordAudit('email_template_updated', {
    userId: session.userId,
    detail: data.id,
  });
  sendJson(res, 200, { ok: true, message: `${definition.label} template saved.` });
});
"}}


