  notes: ['Safe note'],
  reason: 'Reason',
  site: 'https://example.com',
});
assert.match(rendered, /&lt;script&gt;alert\(1\)&lt;\/script&gt;/);
assert.match(rendered, /Go &quot;now&quot;/);
